import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useGetFormQuery, useSubmitResponseMutation, QuestionType } from '../generated/graphql';

const FormFillerPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { data, isLoading, error } = useGetFormQuery({ id: id! });
  const [submitResponse, { isLoading: isSubmitting }] = useSubmitResponseMutation();
  const [answers, setAnswers] = useState<Record<string, any>>({});
  const [submitted, setSubmitted] = useState(false);

  if (isLoading) return <div className="p-8">Loading form...</div>;
  if (error || !data?.form) return <div className="p-8 text-red-500">Error loading form.</div>;

  const form = data.form;

  const handleAnswerChange = (questionId: string, value: any) => {
    setAnswers({ ...answers, [questionId]: value });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const answerInputs = Object.entries(answers).map(([questionId, value]) => ({
      questionId,
      value: typeof value === 'object' ? JSON.stringify(value) : String(value),
    }));

    try {
      await submitResponse({ formId: id!, answers: answerInputs }).unwrap();
      setSubmitted(true);
    } catch (err) {
      alert('Failed to submit form');
    }
  };

  if (submitted) {
    return (
      <div className="max-w-2xl mx-auto p-8 text-center">
        <h1 className="text-3xl font-bold mb-4">Form submitted successfully!</h1>
        <button
          onClick={() => navigate('/')}
          className="text-blue-600 hover:underline"
        >
          Go back to Home
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto p-8 bg-gray-50 min-h-screen">
      <div className="bg-white p-6 rounded-lg shadow-md border-t-8 border-purple-700 mb-6">
        <h1 className="text-4xl font-bold mb-2">{form.title}</h1>
        <p className="text-gray-600">{form.description}</p>
      </div>

      <form onSubmit={handleSubmit}>
        {form.questions.map((q) => (
          <div key={q.id} className="bg-white p-6 rounded-lg shadow-md mb-4">
            <label className="block text-lg font-semibold mb-4">
              {q.title} {q.required && <span className="text-red-500">*</span>}
            </label>

            {q.type === QuestionType.Text && (
              <input
                type="text"
                required={q.required}
                className="w-full border-b outline-none p-2 focus:border-purple-700"
                onChange={(e) => handleAnswerChange(q.id, e.target.value)}
              />
            )}

            {q.type === QuestionType.MultipleChoice && (
              <div className="space-y-2">
                {q.options?.map((opt, i) => (
                  <label key={i} className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="radio"
                      name={q.id}
                      required={q.required}
                      value={opt}
                      onChange={(e) => handleAnswerChange(q.id, e.target.value)}
                    />
                    <span>{opt}</span>
                  </label>
                ))}
              </div>
            )}

            {q.type === QuestionType.Checkbox && (
              <div className="space-y-2">
                {q.options?.map((opt, i) => (
                  <label key={i} className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="checkbox"
                      onChange={(e) => {
                        const current = answers[q.id] || [];
                        const next = e.target.checked
                          ? [...current, opt]
                          : current.filter((o: string) => o !== opt);
                        handleAnswerChange(q.id, next);
                      }}
                    />
                    <span>{opt}</span>
                  </label>
                ))}
              </div>
            )}

            {q.type === QuestionType.Date && (
              <input
                type="date"
                required={q.required}
                className="border p-2 rounded"
                onChange={(e) => handleAnswerChange(q.id, e.target.value)}
              />
            )}
          </div>
        ))}

        <button
          type="submit"
          disabled={isSubmitting}
          className="bg-purple-700 text-white px-8 py-2 rounded hover:bg-purple-800 disabled:bg-gray-400"
        >
          {isSubmitting ? 'Submitting...' : 'Submit'}
        </button>
      </form>
    </div>
  );
};

export default FormFillerPage;
